/* Spoken companion notes; Japanese patterns and Mandarin explanations are separate. */
window.LESSON_NOTES=[
 ['と＋思う','と、おもう。','把前面的内容作为“想”或者“觉得”的内容。引用助词把整句话连接到后面的动词，所以可以理解为“我想”，或者“我觉得”。'],
 ['のだ／んだ','のだ。んだ。','这是解释前面的事情，或者强调自己得出的结论的说法。第二种是第一种的口语缩略，不必逐字翻译成“是”。'],
 ['けれど（も）／けど','けれども。けれど。けど。','连接前后两个内容，意思是“虽然，但是”。它也常放在句尾，让语气更委婉。'],
 ['やっぱり','やっぱり。','意思是“果然”，或者“还是”。常表示事情符合预想，或者想过以后，仍然回到了原来的判断。'],
 ['〜ていく／〜てゆく','ていく。てゆく。','动词用接续形式，再接表示“去”的动词。可以表示做着某事离开，也可以表示一种变化从现在继续发展下去。这两种说法意思接近。'],
 ['〜てくる','てくる。','动词用接续形式，再接表示“来”的动词。可以表示做完某事再回来，也可以表示一种变化一直发展到现在。要结合上下文判断。'],
 ['〜ている','ている。','动词用接续形式，再接表示存在的动词。既可以表示正在做，也可以表示动作完成后留下的状态，例如“住着”或者“知道”。'],
 ['〜てる／〜でる（口语候选）','てる。でる。','日常口语常把表示持续状态的形式缩短，省略其中一个假名。过去形式也会缩短。要结合动词边界判断，不能只凭几个字就确定。'],
 ['〜てしまう','てしまう。','可以表示动作做完了，也可以带有“竟然这样了”，或者“不小心这样了”的心情。口语中经常缩短，所以要结合语气理解。'],
 ['〜てもらう','てもらう。','某人为我，或者为说话人这一方做了某件事，我从中受益。例如，请人帮忙找东西。'],
 ['〜てくれる','てくれる。','别人为我，或者为我这一方做了某件事，强调对方给予的帮助。例如，对方告诉了我。'],
 ['〜てあげる','てあげる。','我，或者句子的主语，为别人做某件事。直接对对方说时，有时会显得像在施恩，要注意说话的场合。'],
 ['〜ておく','ておく。','为了后面的事情，先做好一个动作，或者保持某个状态。它在口语里可能缩短。'],
 ['〜てみる','てみる。','意思是“试着做做看”，看看结果怎么样。这里后面的动词，不是单纯指用眼睛看。'],
 ['〜てある','てある。','有人做完某个动作以后，结果的状态仍然保留着。通常强调事先做过安排或者准备。'],
 ['というか','というか。','意思是“或者说”，或者“更确切地说”。用后面的表达，修正前面刚刚说的话。'],
 ['〜わけだ','わけだ。','说明根据前文得出的结论，可以理解为“也就是说”，或者“难怪”。这个词本来有缘由和道理的意思。'],
 ['〜という','という。','表示命名、引用或者解释，可以理解为“叫作什么的”，或者“所谓的”。先看看它后面修饰的是哪个名词。'],
 ['〜って（口语）','って。','口语中，可以代替引用的说法，也可以把某件事情拿来当作话题。先判断是在转述别人说的话，还是在提示话题。'],
 ['〜ことになる／〜ことにする','ことになる。ことにする。','前一种表示结果或者安排就是这样，后一种表示主语自己决定这样做。重点是分清决定来自谁。'],
 ['〜たことがある','たことがある。','动词的过去形式，接表示“事情”和“存在”的表达，意思是“曾经做过”。如果前面是动词原形，也可能表示“有时会这样”。'],
 ['〜ことができる','ことができる。','动词原形，接这个表达，表示“能够做”。它先把动作变成一个名词单位，再说明可以做这个动作。'],
 ['〜ことに気づく','ことにきづく。','意思是意识到前面说的事实。它先把整件事情变成一个名词单位，再连接到“注意到”这个动词。'],
 ['〜ように','ように。','根据前面的形式，可以表示“像什么一样”，“为了能够做到”，也可以用来转述要求。不要只记住一个固定的中文意思。'],
 ['〜ような＋名词','ような。','表示“像什么一样的”。它后面通常直接修饰一个名词。'],
 ['〜みたい','みたい。','这是口语中的“像”，或者“好像”。后面接名词和修饰动作时，结尾形式会不一样。'],
 ['〜らしい','らしい。','可以根据消息或者迹象表示推测，意思是“好像”或者“听说”。也可以表示具有某种事物应有的特点。'],
 ['〜そうだ','そうだ。','有两种常见用法。接在完整的简体句后面，通常表示“听说”；接在动词连用形式或形容词词干后面，通常表示“看起来”。'],
 ['〜だろう／〜でしょう','だろう。でしょう。','表示推测，意思是“应该是这样吧”，也可以用来向对方确认。后一种说法更加礼貌。'],
 ['〜かもしれない','かもしれない。','表示可能性，意思是“也许”，或者“说不定”。通常不是很有把握的推测。'],
 ['〜はず','はず。','根据某个依据，判断“应该如此”。如果后面接否定表达，也可以表示“按理说不可能”。'],
 ['〜つもり','つもり。','接在动词原形后面，表示“打算做”。如果前面用过去形式，也可以表示自以为已经做过。'],
 ['〜ため（に）','ために。','可以表示目的，意思是“为了”，也可以表示原因，意思是“因为”。先看前面是有意做的动作，还是已经发生的事实。'],
 ['〜のに','のに。','常表示预期和结果相反，可以理解为“明明这样，却那样”。有时也可以表示用途，要结合句子判断。'],
 ['〜ので','ので。','说明原因，意思是“因为”。这个表达通常更侧重客观地解释事情。接名词和某类形容词时，需要相应的连接形式。'],
 ['〜ながら','ながら。','接在动词连用形式后面，通常表示“一边做，一边做”，主要动作在后面。有时也可以表示让步。'],
 ['〜たり〜たりする','たり。たりする。','列举一些有代表性的动作，意思是“做做这个，做做那个等等”。它不表示列出了全部动作。'],
 ['〜たら','たら。','一种条件表达，可以表示“如果”，也可以表示“等做完以后”。小说里还常用来表示做完某件事，发现了新情况。'],
 ['〜なら','なら。','承接某个话题或者假设，可以理解为“如果是这样的话”，或者“说到这件事情”。'],
 ['〜ても／〜でも','ても。でも。','连接在条件后面时，表示“即使这样，也仍然那样”。其中一种形式还可以表示“但是”，或者用来举例，要结合边界判断。'],
 ['〜しか〜ない','しか。ない。','与否定搭配，表示“只有”。中文翻译看起来是肯定，日语表达的形式却是否定。'],
 ['〜だけ','だけ。','限定范围，意思是“只”，或者“仅仅”。如果接在动词可能形式后面，还可以表示尽可能做到。'],
 ['〜ばかり','ばかり。','可以表示“净是”，或者“只顾着”。如果接在动词过去形式后面，则可以表示“刚刚做完”。'],
 ['〜ほど','ほど。','表示程度或者比较，可以理解为“到那种程度”。搭配条件形式，还可以表示“越怎么样，就越怎么样”。'],
 ['〜くらい／〜ぐらい','くらい。ぐらい。','表示大约的数量或者程度，可以理解为“大约”，“左右”，或者“到这样的程度”。'],
 ['〜より','より。','在比较中，标出比较的基准，意思是“比”。如果同时出现表示某一方的表达，注意分清哪一方更加突出。'],
 ['〜まま','まま。','保持原来的状态，没有改变。例如，保持坐着的状态，再去做别的事情。'],
 ['〜うちに','うちに。','在某个状态持续的期间做一件事，或者在不知不觉之间发生了变化。'],
 ['〜たとたん（に）','たとたんに。','前面的动作刚一完成，后面的事情就发生了。强调两件事紧接着发生。'],
 ['〜なければ／〜なきゃ','なければ。なきゃ。','完整的条件表达，意思是“不这样做的话”。口语中常把后面的“不行”省略，整句话就表示“必须这样做”。'],
 ['〜なくて／〜ないで','なくて。ないで。','前一种常用来连接状态或者说明原因，后一种常表示不做前面的动作，而去做后面的动作。两者不能总是互换。'],
 ['〜ず（に）','ずに。','比较书面的否定连接，意思是“不做这个，而做那个”。通常接近另一个常用的否定连接，但部分动词的变化是特殊的。'],
 ['〜れる／〜られる（形式候选）','れる。られる。','可能是被动、可能、尊敬或者自发的形式。必须结合动词原形和主语来判断，不能看到这个词尾，就断定一定是被动。'],
 ['使役形式（候选）','せる。させる。','可以表示“让某人做”，或者“使某人做”。先确认这确实是当前动词的使役变化，而不是另一个单词的一部分。'],
 ['〜すぎる','すぎる。','接动词的连用形式，或者形容词词干，表示做得过多，或者过于某种状态。'],
 ['〜てほしい','てほしい。','表示希望别人做某件事情。动作的执行者，通常由相应的助词标出来。'],
 ['〜たほうがいい','たほうがいい。','提出建议，意思是“最好这样做”，或者“这样做比较好”。这里的过去形式，并不表示事情已经发生。'],
 ['〜てもいい','てもいい。','表示允许或者可以接受，意思是“可以这样做”，或者“即使这样也没关系”。'],
 ['〜てはいけない','てはいけない。','表示禁止，意思是“不可以这样做”。口语中，连接部分常会缩短。'],
 ['〜おかげ／〜せい','おかげ。せい。','用来说明结果的原因。前一种多用在好结果上，后一种多用在不好的结果上。'],
 ['土佐方言提示','しゆう。しちゅう。やき。','本书人物经常说高知的土佐方言。有些形式表示正在进行，有些表示结果状态，也有表示原因和判断的说法。它们的具体意思，需要按上下文理解。'],
 ['方言口语提示','や。やろ。','在一些西日本方言里，常用和标准语不同的判断词尾。也有接近推测的说法。注意不要把判断词尾和列举助词混在一起。'],
 ['ある → あった','ある。あった。','前一个是动词原形，意思是“有”。后一个是它的过去形式，意思是“有过”。这里的问题，是过去发生过的。'],
 ['〜けれど','けれど。','意思是“虽然，但是”。前面承认有过问题，后面转向叙述者现在的感受。'],
 ['戻る → 戻って＋ゆく','もどる。もどってゆく。','前一个动词表示“回到”。变成接续形式，再接表示“去”的动词，说明事情最后还是朝这个方向发展。'],
 ['〜んだ','んだ。','这是说明情况或者得出结论的口语形式，带着一种解释的语气。'],
 ['内容＋と＋思う','と、おもう。','引用助词把前面的整个判断，连接到表示“想”或者“认为”的动词。这里可以理解为“我觉得”。']
];
window.PARTICLE_NOTES={
 'は':'提示话题，可以理解为“说到什么”。作助词时，读音要特别留意。',
 'た':'表示过去或者完成。接在某些动词后面时，这个词尾会有相应的音变。',
 'けれど':'连接前后内容，表示“虽然，但是”。',
 'けど':'这是比较口语的连接说法，表示“虽然，但是”。',
 'に':'可以标记时间、地点、对象、目的，或者变化的结果。结合前面的词和后面的动词判断。',
 'て':'连接动作或者状态。后面再接其他动词时，常常组成一个完整的语法结构。',
 'だ':'表示判断，意思是“是”。这是比较随意的普通体形式。',
 'と':'可以表示“和”，也可以引用别人说的话或者自己的想法。有时还表示条件，要结合句型判断。',
 'の':'可以表示所属，相当于中文的“的”；也可以把前面的整句话，作为一个名词单位来使用。',
 'を':'通常标记动作的对象，有时也标记经过或者离开的地点。作助词时，要留意它的实际读音。',
 'か':'可以表示疑问或者选择，意思是“吗”，或者“还是”。',
 'が':'常用来标记主语。有时也表示转折，需要结合前后内容判断。',
 'で':'可以表示动作发生的地点或者采用的手段。有时也属于判断表达的连接形式。',
 'も':'意思是“也”，有时还强调“连什么都这样”。',
 'ので':'用来说明原因，可以理解为“因为”。',
 'から':'可以表示从某个地方或时间开始，也可以说明原因，意思是“因为”。',
 'くらい':'表示大约的数量或者程度，可以理解为“大约”，“左右”，或者“到这样的程度”。',
 'ぐらい':'这是表示大约的口语说法，意思是“大约”，“左右”，或者“到这样的程度”。',
 'らしい':'可以表示根据消息或迹象推测，“似乎”或者“听说”；有时也表示具有某种特点。',
 'とか':'可以列举“什么之类的”，有时也用来转述听说的事情。',
 'なんか':'是比较随意的口语表达，可以表示“什么之类”，或者带着一种含糊、轻描淡写的语气。',
 'う':'这是意志或者推测的词尾，要接在动词或判断形式后面，不能当作独立单词。',
 'ん':'可能是把一个常用形式缩短了，也可能属于否定表达。请结合前后内容来判断。',
 'な':'放在句末可以表示感叹。如果直接接在动词原形后面，也可以表示禁止。',
 'ない':'表示否定，意思是“不”，或者“没有”。',
 'だけ':'限定范围，意思是“只”，或者“仅仅”。',
 'って':'口语中常用来引用话语，或者提示话题。先看看前面是在转述，还是在提出一件事情。',
 'ながら':'通常表示“一边做，一边做”，有时也表示让步。',
 'や':'可以是列举助词；在某些方言里，也可能是判断的说法。',
 'まで':'可以表示“到什么为止”，有时也强调“甚至到了这个程度”。',
 'し':'可以列举理由或者并列事实，意思接近“既这样，又那样”。',
 'でも':'可以表示“即使这样，也仍然那样”，也可以举例或者表示转折。要结合上下文判断。',
 'ます':'让动词的说法更礼貌。阅读时，可以先找到动词原形，再观察词尾。',
 'ば':'通常表示条件，可以理解为“如果这样”。',
 'たい':'接在动词后面，表示“想做某件事”。',
 'よ':'提醒或者告诉对方一件事，常用来加强句末的语气。',
 'ね':'可以征求对方认同，或者表达和对方的共同感受。',
 'ぞ':'是较强、较随意的句末说法，用来强调自己的判断。',
 'のに':'常表示“明明这样，却那样”。有时也属于表示用途的表达。',
 'へ':'标记移动的方向，意思是“向哪里”。作助词时，要留意实际读音。',
 'たり':'列举有代表性的动作，可以理解为“做做这个，做做那个等等”。',
 'より':'可以表示比较的基准，也可能表示起点。具体意思要看上下文。',
 'ある':'表示有或者存在，通常用于没有生命的事物。',
 'ほど':'表示程度，也可以用于比较，或者表示“越怎么样，就越怎么样”。',
 'です':'表示判断的礼貌体，可以理解为比较礼貌的“是”。',
 'しか':'通常和否定搭配，表示“只有”。',
 'べし':'比较书面的表达，可以表示“应该”，或者“理当如此”。',
 'ぬ':'是一种书面或者较旧式的否定形式，意思是“不”，或者“没有”。',
 'じゃん':'是随意的句末表达，有时可以理解为“不是这样嘛”。',
 'なあ':'表示感叹、商量或者自言自语的语气，也要结合人物说话的情境。',
 'など':'表示“什么等等”，用来列举一些例子。',
 '*':'这部分可能是口语、方言或者自动分词留下的片段。请先和前后内容一起读，再结合完整句子判断作用。'
};
